class Solution {
public:
    string frequencySort(string s) {
        unordered_map<char,int> ump;
        for(auto it:s)
            ump[it]+=1;
        priority_queue<pair<int,char>> pq;
        string ans="";
        for(auto it:ump)
            pq.push({it.second,it.first});
        while(!pq.empty())
        {
            int cnt=pq.top().first;
            char ch=pq.top().second;
            pq.pop();
            while(cnt--)
                ans+=ch;
        }
        return ans;
    }
};

class Solution {
public:
    string frequencySort(string s) {
        unordered_map<char, int> d;
        for (int i = 0; i < s.length(); i++) {
            d[s[i]] += 1;
        }
        vector<pair<char, int>> d_vec(d.begin(), d.end());
        sort(d_vec.begin(), d_vec.end(), [](const pair<char, int>& p1, const pair<char, int>& p2){
            return p1.second > p2.second;
        });
        string ans = "";
        for (int i = 0; i < d_vec.size(); i++) {
            for (int j = 0; j < d_vec[i].second; j++) {
                ans += d_vec[i].first;
            }
        }
        return ans;
    }
};

class Solution {
    public String frequencySort(String s) {
        Map<Character, Integer> d = new HashMap<Character, Integer>();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            int freq = d.getOrDefault(c, 0) + 1;
            d.put(c, freq);
        }
        List<Character> d_list = new ArrayList<Character>(d.keySet());
        Collections.sort(d_list, (a, b) -> d.get(b) - d.get(a));
        StringBuffer sb = new StringBuffer();
        for (int i = 0; i < d_list.size(); i++) {
            char c = d_list.get(i);
            for (int j = 0; j < d.get(c); j++) {
                sb.append(c);
            }
        }
        return sb.toString();
    }
}
